import{frequencyCategories,frequencyInput,matchFrequency,frequencyDrilldown}from'./match-frequency.js';
import{currentPrivateMatches}from'./current-private-matches.js';import{currentFrequencyInput}from'./current-frequency.js';
import{cohortLabels as originalCohortLabels}from'./model-match-audit.js';
import{newCohortLabels,selectCohortPopulation}from'./cohort-049-meta.js';
const cohortLabels={...originalCohortLabels,...newCohortLabels};
import{authClient,getPrivateReviewCases}from'./firebase-client.js?v=0.47.0';
const $=id=>document.getElementById(id),h=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;'),labels=Object.fromEntries(frequencyCategories.map(c=>[c.id,c.title])),extraLabels={pending:'Awaiting confirmation',invitations:'Comparison invitation',beyondLists:'Eligible beyond displayed lists'},absenceLabels={'never-offered':'Absent from current result data','confirmation-only':'Awaiting confirmation','comparison-only':'Comparison invitation','beyond-displayed-lists':'Only beyond the displayed lists'};
let data=null,publicRows=[],privateRows=[],result=null,professionView=[],missingView=[],expanded=false,privateGeneration=0,userId=null;
const allRows=()=>[...publicRows,...privateRows],population=()=>selectCohortPopulation(allRows(),$('cohort').value),options=()=>({cohort:'all',education:$('education').value,fieldUnit:$('field-unit').value}),fieldNames=ids=>ids.map(id=>data.catalog.fields.find(f=>f.id===id)?.title||id).join(' · '),professionName=id=>data.catalog.professions.find(p=>p.id===id)?.title||id;
function saveView(){const u=new URL(location.href);for(const[id,key]of[['cohort','cohort'],['education','education'],['field-unit','unit'],['career-search','query'],['career-field','field'],['sort','sort'],['absence','absence']]){const value=$(id).value;if(value&&value!=='all'&&!(key==='unit'&&value==='models')&&!(key==='sort'&&value==='top'))u.searchParams.set(key,value);else u.searchParams.delete(key);}history.replaceState(null,'',u);}
const countButton=(n,type,id,category)=>'<button data-type="'+type+'" data-id="'+h(id)+'" data-category="'+category+'"'+(!n?' disabled':'')+' aria-label="'+h((labels[category]||'Any match')+': '+n+' · '+(type==='field'?data.catalog.fields.find(r=>r.id===id)?.title:professionName(id)))+'">'+n+'</button>';
function renderFields(){const offers=result.fieldUnit==='offers',rows=[...result.fields].sort((a,b)=>b.counts.top-a.counts.top||a.title.localeCompare(b.title)),max=Math.max(1,...rows.flatMap(r=>frequencyCategories.map(c=>r.counts[c.id]))),scale=Math.max(5,Math.ceil(max/5)*5);$('field-note').textContent=offers?'Each model–profession pair contributes once to every catalog field attached to that profession. One model can generate several offers in one field. Cross-field careers contribute to multiple fields.':'Each field counts once per model within each category, even when that model receives several professions in the same field. Cross-field professions can contribute to several fields.';$('field-scale').textContent='Common bar scale: 0–'+scale+' '+(offers?'profession offers':'models')+'. Select a field or count to inspect its models.';
 $('field-chart').innerHTML=rows.map(r=>'<article class="field-row" role="listitem"><div><button class="field-name" data-type="field" data-id="'+h(r.id)+'" data-category="any">'+h(r.title)+'</button><small>'+r.professionIds.length+' catalog professions in this education view</small></div><div>'+frequencyCategories.map(c=>'<div class="series '+c.id+'"><span>'+c.title+'</span><div class="track" aria-hidden="true"><div class="fill" style="--size:'+r.counts[c.id]/scale*100+'%"></div></div>'+countButton(r.counts[c.id],'field',r.id,c.id)+'</div>').join('')+'</div></article>').join('');
}
function renderProfessions(){if(!result)return;const q=$('career-search').value.trim().toLowerCase(),field=$('career-field').value,sort=$('sort').value;professionView=result.professions.filter(r=>(field==='all'||r.fieldIds.includes(field))&&(!q||[r.title,r.id,fieldNames(r.fieldIds)].join(' ').toLowerCase().includes(q))).sort((a,b)=>sort==='name'?a.title.localeCompare(b.title):b.counts[sort]-a.counts[sort]||b.counts.top-a.counts.top||a.title.localeCompare(b.title));const shown=result.models?professionView.slice(0,expanded?Infinity:20):[],scale=Math.max(1,result.models);
 $('career-count').textContent=result.models?professionView.length+' professions in this search · '+shown.length+' shown. Bars share a 0–'+result.models+' model scale.':'No models are available in this cohort; profession frequencies are not assessed.';
 $('profession-rows').innerHTML=shown.map(r=>'<tr><th scope="row"><button class="career-name" data-type="profession" data-id="'+h(r.id)+'" data-category="any">'+h(r.title)+'</button><small>'+h(fieldNames(r.fieldIds))+'</small></th>'+frequencyCategories.map(c=>'<td><div class="count-cell '+c.id+'"><div class="track" aria-hidden="true"><div class="fill" style="--size:'+r.counts[c.id]/scale*100+'%"></div></div>'+countButton(r.counts[c.id],'profession',r.id,c.id)+'</div></td>').join('')+'<td class="any-count">'+countButton(r.counts.any,'profession',r.id,'any')+'</td></tr>').join('')||'<tr><td colspan="5">'+(result.models?'No professions match this search.':'No model results available in this cohort. Sign in to include owner-only models.')+'</td></tr>';
 $('show-more').hidden=!result.models||professionView.length<=20;$('show-more').textContent=expanded?'Show first 20 professions':'Show all '+professionView.length+' professions';
}
function renderMissing(){if(!result)return;const mode=$('absence').value;missingView=result.missing.filter(r=>mode==='all'||mode==='unoffered'&&!r.displayedExposure.length||mode==='pending'&&r.pending.length||mode==='invited'&&r.invitations.length).sort((a,b)=>a.title.localeCompare(b.title));$('absence-count').textContent=result.models?missingView.length+' professions in this list · '+result.missing.length+' with no appearances in the three match lists · '+result.never.length+' not currently displayed in the model chart.':'No model results in this cohort; absence cannot be assessed.';
 $('missing-list').innerHTML=missingView.map(r=>'<article class="missing-card"><button class="career-name" data-type="profession" data-id="'+h(r.id)+'" data-category="exposure">'+h(r.title)+'</button><small>'+h(fieldNames(r.fieldIds))+'</small><span class="status '+(!r.displayedExposure.length?'absent':'')+'">'+h(r.topEligible===false?'Browse only · insufficient specific evidence':absenceLabels[r.absence])+'</span><p>Top <strong>0</strong> · Other <strong>0</strong> · Sustains lifestyle <strong>0</strong></p><p>'+r.pending.length+' model'+(r.pending.length===1?'':'s')+' awaiting confirmation · '+r.invitations.length+' comparison invitation'+(r.invitations.length===1?'':'s')+'</p>'+(r.beyondLists.length?'<small>Also exists among internal eligible options for '+r.beyondLists.length+' model'+(r.beyondLists.length===1?'':'s')+'; it is not shown in their three match lists.</small>':'')+'<p><a href="../#/'+(r.expandedDegree?'journey/degree-check/':'career/')+encodeURIComponent(r.id)+'">Explore this profession ↗</a></p></article>').join('')||'<p class="empty">'+(!result.models?'Choose a cohort with available model results to assess missing professions.':mode==='unoffered'?'Every profession in this education view is displayed in the selected model-chart results, including pending checks or comparison invitations.':'No professions meet this absence filter.')+'</p>';
}
function render(){if(!data)return;result=matchFrequency(population(),data.catalog,options());const privateCount=privateRows.length,scope=cohortLabels[$('cohort').value]||($('cohort').value==='all-rows'?'Base profiles + diagnostic variants':'All base profiles');$('scope').textContent=scope+' · Current rerun '+data.version+' · '+data.asOf+' · '+result.models+' models · '+result.professions.length+' catalog professions in the selected education routes';$('models').textContent=result.models;$('listed').textContent=result.models?result.listedProfessions:'—';$('missing').textContent=result.models?result.missing.length:'—';$('unoffered').textContent=result.models?result.never.length:'—';$('profession-totals').textContent=result.totals.top+' Top offers · '+result.totals.other+' Other offers · '+result.totals.sustaining+' displayed lifestyle options. “Any of these lists” counts unique models per profession, not the sum of the three columns.';for(const b of document.querySelectorAll('[data-export]'))b.disabled=!result.models;renderFields();renderProfessions();renderMissing();}
function openDetail(type,id,category){if(!result)return;const r=(type==='field'?result.fields:result.professions).find(r=>r.id===id);if(!r)return;const rows=frequencyDrilldown(result,population(),{type,id,category}),pairs=rows.reduce((n,m)=>n+m.appearances.length,0),categoryName=labels[category]|| (category==='exposure'?'All current result references':'Any of the three match lists');$('detail-content').innerHTML='<h2 id="detail-title">'+h(r.title)+'</h2><p class="detail-meta">'+h(categoryName)+' · '+rows.length+' model'+(rows.length===1?'':'s')+' · '+pairs+' list appearances</p><p class="definition">A profession may appear in several categories for one model. Open a model to compare its profile, saved structured answers, current matches and budget.</p>'+(type==='profession'?'<p class="detail-label">Top '+r.counts.top+' · Other '+r.counts.other+' · Sustains lifestyle '+r.counts.sustaining+'</p><p>'+h(r.routes.map(x=>x.label).join(' · '))+'</p>':'<p>'+h(result.fieldUnit==='offers'?'The chart counts profession offers; this list groups those offers by model.':'The chart counts each model once per field and category.')+'</p>')+(rows.length?'<ul class="model-list">'+rows.map(m=>'<li><a href="./model-match-chart.html?cohort=all-rows&amp;query='+encodeURIComponent(m.id)+'">'+h(m.name)+' · '+h(m.id)+' ↗</a><small> · '+h(cohortLabels[m.phase]||m.phase)+(m.cohort049?.kind==='diagnostic'?' · Diagnostic variant'+(m.cohort049.baseId?' · Parent: <a href="./model-match-chart.html?cohort=all-rows&amp;query='+encodeURIComponent(m.cohort049.baseId)+'">'+h(m.cohort049.baseId)+' →</a>':''):'')+'</small>'+[...new Set(m.appearances.map(a=>a.category))].map(k=>'<p><strong>'+h(labels[k]||extraLabels[k])+'</strong>: '+h(m.appearances.filter(a=>a.category===k).map(a=>professionName(a.id)).join(' · '))+'</p>').join('')+'</li>').join('')+'</ul>':'<p>No model has this profession in the selected lists. '+(category==='any'&&type==='profession'&&r.allExposure.length?'<button data-type="profession" data-id="'+h(id)+'" data-category="exposure">Inspect current references beyond displayed lists →</button>':'')+'</p>')+(type==='profession'?'<p><a href="../#/'+(r.expandedDegree?'journey/degree-check/':'career/')+encodeURIComponent(id)+'">Open profession and preparation details ↗</a></p>':'');if(!$('frequency-detail').open)$('frequency-detail').showModal();$('frequency-detail').scrollTop=0;}
function exportView(kind){if(!result?.models)return;const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';let out;if(kind==='fields')out=[['Field','Unit','Models in scope','Top match','Other match','Sustains lifestyle'],...result.fields.map(r=>[r.title,result.fieldUnit,result.models,r.counts.top,r.counts.other,r.counts.sustaining])];else{const rows=kind==='missing'?missingView:professionView;out=[['Profession ID','Profession','General fields','Models in scope','Top match','Other match','Sustains lifestyle','Any of three lists: unique models','Awaiting confirmation','Comparison invitation','Internal eligible references','Not displayed in model chart','Absence status'],...rows.map(r=>[r.id,r.title,fieldNames(r.fieldIds),result.models,r.counts.top,r.counts.other,r.counts.sustaining,r.counts.any,r.pending.length,r.invitations.length,r.beyondLists.length,!r.displayedExposure.length,r.absence==='listed'?'Listed':absenceLabels[r.absence]])];}const u=URL.createObjectURL(new Blob(['\uFEFF'+out.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='fieldguide-match-frequency-'+kind+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
for(const id of['cohort','education','field-unit'])$(id).addEventListener('change',()=>{expanded=false;saveView();$('frequency-detail').close();$('detail-content').replaceChildren();render();});for(const id of['career-search','career-field','sort'])$(id).addEventListener(id==='career-search'?'input':'change',()=>{expanded=false;saveView();renderProfessions();});$('absence').addEventListener('change',()=>{saveView();renderMissing();});$('show-more').addEventListener('click',()=>{expanded=!expanded;renderProfessions();});$('close-detail').addEventListener('click',()=>$('frequency-detail').close());$('reset').addEventListener('click',()=>{for(const id of['cohort','education','career-field','absence'])$(id).value='all';$('field-unit').value='models';$('career-search').value='';$('sort').value='top';expanded=false;saveView();$('frequency-detail').close();$('detail-content').replaceChildren();render();});document.addEventListener('click',e=>{const b=e.target.closest('button[data-type]');if(b&&!b.disabled)openDetail(b.dataset.type,b.dataset.id,b.dataset.category);const ex=e.target.closest('[data-export]');if(ex&&!ex.disabled)exportView(ex.dataset.export);});
function clearPrivate(){privateRows=[];$('frequency-detail').close();$('detail-content').replaceChildren();render();}
async function loadPrivate(){const request=++privateGeneration,session=await authClient.getSession(),user=session.data?.user;if(request!==privateGeneration)return;userId=user?.id||null;clearPrivate();$('sign-in').hidden=!!user;$('sign-out').hidden=!user;if(user){try{const cases=await getPrivateReviewCases(),current=(await authClient.getSession()).data?.user;if(request!==privateGeneration||current?.id!==user.id)return;privateRows=cases.map(c=>currentFrequencyInput(currentPrivateMatches(c)));$('access-status').textContent=publicRows.length+' public models + '+privateRows.length+' owner-only models.';}catch{if(request!==privateGeneration)return;$('access-status').textContent=publicRows.length+' public models. This account cannot load the owner-only models.';}}else $('access-status').textContent=publicRows.length+' public models. Sign in to include six owner-only models.';render();}
$('sign-in').addEventListener('click',async()=>{try{await authClient.googleSignIn();await loadPrivate();}catch{$('access-status').textContent='Sign in on the published Fieldguide site to include owner-only models.';}});$('sign-out').addEventListener('click',async()=>{await authClient.signOut();});
try{const response=await fetch('./match-frequency-data.json',{cache:'no-store'});if(!response.ok)throw Error('The current frequency data could not load.');data=await response.json();publicRows=[...data.rows,...(data.diagnosticRows||[])];$('cohort').innerHTML='<option value="all">All base profiles</option><option value="all-rows">Base profiles + diagnostic variants</option>'+Object.entries(cohortLabels).map(([id,title])=>'<option value="'+id+'">'+h(title)+'</option>').join('');$('career-field').innerHTML='<option value="all">All fields</option>'+data.catalog.fields.map(f=>'<option value="'+f.id+'">'+h(f.title)+'</option>').join('');const p=new URL(location.href).searchParams;for(const[id,key]of[['cohort','cohort'],['education','education'],['field-unit','unit'],['career-field','field'],['sort','sort'],['absence','absence']])if([...$(id).options].some(o=>o.value===p.get(key)))$(id).value=p.get(key);$('career-search').value=p.get('query')||'';$('source-notes').innerHTML='<p>Current rerun '+h(data.version)+' · '+h(data.asOf)+'. Source: <a href="./model-match-chart.html">Interactive model match chart</a> and the '+data.catalog.professions.length+'-profession matching and browse catalog. The additional simulator has bindings for '+data.simulation.bindingCoverage.mappedCareers+' of '+data.simulation.bindingCoverage.accessibleCareers+' careers; a zero count may reflect missing simulation coverage. No career-frequency target is imposed. Rebuilt with every site build. Base profiles are the default denominator and CSV population; diagnostic variants enter only when explicitly selected.</p><ol>'+data.methods.map(m=>'<li>'+h(m)+'</li>').join('')+'</ol><p><a href="./match-frequency-data.json">Public counts, catalog and model–profession references · JSON ↗</a>. Owner-only models are computed in this browser after sign-in; their records are not in that public file.</p>';render();await loadPrivate();authClient.watch(next=>{if((next?.id||null)!==userId){privateGeneration++;clearPrivate();loadPrivate();}});}catch(e){$('access-status').textContent=e.message||'The frequency chart could not load.';}
